 "decisions": [
  {
   "date": "2026-07-27",
   "title": "Hub plus Hosted Control Planes",
   "area": "Architecture",
   "rejected": "A dedicated control plane per cluster",
   "issue": 391,
   "why": "Hardware efficiency and fast cluster creation; the hub becomes the critical control point"
  },
  {
   "date": "2026-07-27",
   "title": "Two-stage build: dev on ESI, prod on dedicated hardware",
   "area": "Delivery",
   "rejected": "Wait for RHOSO 18",
   "issue": 311,
   "why": "RHOSO was not ready and the stack had to be proven quickly"
  },
  {
   "date": "2026-07-29",
   "title": "Keycloak as the sole IdP, federated via CILogon",
   "area": "Identity",
   "rejected": "A separate IdP for the NIST environment",
   "issue": 282,
   "why": "One identity platform; a single option holds under 800-171"
  },
  {
   "date": "2026-08-03",
   "title": "Keycloak on AWS EKS in the MOC account, as a pilot",
   "area": "Identity",
   "rejected": "GovCloud, on-premises, ECS, EC2",
   "issue": 359,
   "why": "The IdP must survive a cluster outage; reuses Kubernetes skills; compliance deferred"
  },
  {
   "date": "2026-08-17",
   "title": "Argo CD + Helm + ACM Placements instead of ai-ivp",
   "area": "Configuration",
   "rejected": "The consultants' Ansible-driven pattern",
   "issue": 51,
   "why": "Simpler and offers more control over what is deployed"
  },
  {
   "date": "2026-08-17",
   "title": "Only pre-registered users may authenticate, on every cluster",
   "area": "Identity",
   "rejected": "The MOC 1.0 model: anyone may log in, with no privileges",
   "issue": 400,
   "why": "NIST requires it and there is a single login front end"
  },
  {
   "date": "2026-08-17",
   "title": "S3 through an in-cluster reverse proxy on a Multus storage network",
   "area": "Storage",
   "rejected": "Host routing, per-namespace attachments, default-gateway routing",
   "issue": 404,
   "why": "Keeps the fast storage path with minimal tenant configuration and no route leakage"
  },
  {
   "date": "2026-08-17",
   "title": "No RDMA or SR-IOV for the Open Accelerator",
   "area": "Network",
   "rejected": "Configuring the NIC operators",
   "issue": 421,
   "why": "Not needed by current workloads; the capability stays available but unenabled"
  },
  {
   "date": "2026-08-25",
   "title": "Tenant projects from a Git values file, not ColdFront",
   "area": "Tenancy",
   "rejected": "ColdFront, as used in MOC 1.0",
   "issue": 438,
   "why": "Saves engineering time for the NIST build"
  },
  {
   "date": "2026-08-26",
   "title": "Three-tier ANP / NetworkPolicy / BANP tenant isolation",
   "area": "Network",
   "rejected": "A single admin policy",
   "issue": 441,
   "why": "One tier cannot express both an admin guarantee and tenant flexibility"
  },
  {
   "date": "2026-08-31",
   "title": "HAProxy on the firewall for hosted-cluster endpoints",
   "area": "Network",
   "rejected": "MetalLB plus port forwarding everywhere",
   "issue": 422,
   "why": "Simpler for services that are NodePorts anyway"
  },
  {
   "date": "2026-09-15",
   "title": "Bill the Open Accelerator by allocation",
   "area": "Billing",
   "rejected": "Usage-based metering",
   "issue": 455,
   "why": "Market norm; the cost is incurred whether or not the GPU is busy"
  }
 ],
 "discoveries": [
  {
   "date": "2026-08-26",
   "title": "Cross-namespace isolation bypassed using FQDN",
   "severity": "critical",
   "status": "fixed",
   "issue": 441,
   "found_by": "UAT harness",
   "detail": "A tenant could reach another tenant's service by its full DNS name. Short names only appeared to fail because of DNS search paths, not because anything was blocked. Fixed with the three-tier policy design."
  },
  {
   "date": "2026-09-08",
   "title": "Billing metric absent under Hosted Control Planes",
   "severity": "serious",
   "status": "open",
   "issue": 481,
   "found_by": "Observability rollout",
   "detail": "kube_pod_resource_request is published only by the kube-scheduler, which under HCP runs on the hub rather than in the cluster. The workload cluster's Prometheus cannot see it, so invoice data is missing. Forces the 4.22 upgrade."
  },
  {
   "date": "2026-09-14",
   "title": "Namespace policy blocked all internet egress",
   "severity": "serious",
   "status": "fixed",
   "issue": 491,
   "found_by": "User report",
   "detail": "The first tenant NetworkPolicy allowed egress only within the namespace, silently breaking pip, git and Go module downloads. Fixed by allowing 0.0.0.0/0 except the pod and service CIDRs."
  },
  {
   "date": "2026-08-21",
   "title": "ConnectX-7 NICs are the non-crypto variant",
   "severity": "warning",
   "status": "open",
   "issue": 351,
   "found_by": "Hardware audit",
   "detail": "No hardware TLS offload, so the CPU pays for all encryption in transit. Matters for NIST, where encryption is mandatory."
  },
  {
   "date": "2026-09-11",
   "title": "Logout does not invalidate the Keycloak session",
   "severity": "warning",
   "status": "open",
   "issue": 487,
   "found_by": "Onboarding",
   "detail": "The console session ends but the SSO session persists, so the next login is silent. Needs logoutRedirect pointed at Keycloak's end-session endpoint."
  },
  {
   "date": "2026-09-16",
   "title": "Object storage proxy deployed on only one cluster",
   "severity": "warning",
   "status": "open",
   "issue": 500,
   "found_by": "Platform review",
   "detail": "Centralised multi-cluster observability needs S3 on the hubs, which needs the proxy there first."
  }
 ],
